/* ── Cascading bounce pop-in ───────────────────────────────────────────────
 *
 * The desktop counterpart of the mobile `bouncePopIn` (index.css): a settle with
 * three decaying overshoots rather than `popIn`'s single one. Because the chrome
 * now persists across navigations, this cascade IS the page transition — every
 * screen's blocks rise in sequence as the slot swaps.
 *
 * Usage: put `.dt-cascade` on a container to auto-index its direct children, or
 * `.dt-rise` on any element and set `--dt-i` (step) / `--dt-d` (extra delay).
 */
@keyframes desktopBounceIn {
  0% {
    opacity: 0;
    transform: translateY(26px) scale(0.88);
  }
  55% {
    opacity: 1;
    transform: translateY(-6px) scale(1.035);
  }
  74% {
    transform: translateY(2.5px) scale(0.987);
  }
  88% {
    transform: translateY(-1.2px) scale(1.005);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.dt-rise,
.dt-cascade > * {
  opacity: 0;
  animation: desktopBounceIn 0.54s cubic-bezier(0.34, 1.56, 0.64, 1) both;
  animation-delay: calc(var(--dt-i, 0) * 52ms + var(--dt-d, 0ms));
}

/* Auto-index for `.dt-cascade` containers. Ten steps covers the densest screen
   (settings); anything beyond simply lands on the last step. */
.dt-cascade > *:nth-child(1) { --dt-i: 0; }
.dt-cascade > *:nth-child(2) { --dt-i: 1; }
.dt-cascade > *:nth-child(3) { --dt-i: 2; }
.dt-cascade > *:nth-child(4) { --dt-i: 3; }
.dt-cascade > *:nth-child(5) { --dt-i: 4; }
.dt-cascade > *:nth-child(6) { --dt-i: 5; }
.dt-cascade > *:nth-child(7) { --dt-i: 6; }
.dt-cascade > *:nth-child(8) { --dt-i: 7; }
.dt-cascade > *:nth-child(9) { --dt-i: 8; }
.dt-cascade > *:nth-child(n + 10) { --dt-i: 9; }

